(()=>{'use strict';const main=document.getElementById('main-content');if(!main)return;let sb=null,busy=false;
function client(){if(sb)return sb;const cfg=window.PATIYIZ_CONFIG;if(!cfg?.supabaseUrl||!cfg?.supabasePublishableKey||!window.supabase?.createClient)throw Error('Bağlantı henüz hazır değil');sb=window.supabase.createClient(cfg.supabaseUrl,cfg.supabasePublishableKey);return sb}
function getUI(){let overlay=document.getElementById('buchee-trending-overlay');if(overlay)return overlay;overlay=document.createElement('div');overlay.id='buchee-trending-overlay';overlay.hidden=true;overlay.innerHTML='<div class="buchee-trending-panel" role="dialog" aria-modal="true" aria-label="Gündemdeki Tweetler"><header><button type="button" data-trending-close aria-label="Geri dön">←</button><strong>Gündemdeki Tweetler</strong><small>Son 7 gün</small></header><div class="buchee-trending-list" aria-live="polite"></div></div>';document.body.append(overlay);overlay.querySelector('[data-trending-close]').addEventListener('click',close);return overlay}
function close(){getUI().hidden=true;document.body.classList.remove('buchee-trending-open')}
async function open(){const root=getUI();root.hidden=false;document.body.classList.add('buchee-trending-open');const list=root.querySelector('.buchee-trending-list');list.replaceChildren();list.textContent='Gündemdeki yazılar yükleniyor…';if(busy)return;busy=true;try{const db=client();const since=new Date(Date.now()-7*864e5).toISOString();const {data:posts,error}=await db.from('posts').select('id,author_id,body,created_at,post_format,image_url,video_url').eq('post_format','post').gte('created_at',since).order('created_at',{ascending:false}).limit(150);if(error)throw error;const entries=(posts||[]).filter(p=>p.body?.trim()&&!p.image_url&&!p.video_url);const ids=entries.map(p=>p.id);if(!ids.length){list.textContent='Son 7 günde henüz gündeme girecek kısa yazı bulunmuyor.';return}const [likes,comments,profiles]=await Promise.all([db.from('post_likes').select('post_id').in('post_id',ids),db.from('comments').select('post_id').in('post_id',ids),db.from('profiles').select('id,display_name,handle').in('id',[...new Set(entries.map(p=>p.author_id))])]);for(const r of [likes,comments,profiles])if(r.error)throw r.error;const count=(items)=>{const m=new Map();for(const x of items||[])m.set(x.post_id,(m.get(x.post_id)||0)+1);return m};const lm=count(likes.data),cm=count(comments.data),people=new Map(profiles.data.map(p=>[p.id,p]));entries.sort((a,b)=>((lm.get(b.id)||0)+2*(cm.get(b.id)||0))-((lm.get(a.id)||0)+2*(cm.get(a.id)||0))||Date.parse(b.created_at)-Date.parse(a.created_at));list.replaceChildren();for(const p of entries.slice(0,30)){const item=document.createElement('article');item.className='buchee-trending-item';const title=document.createElement('strong');const person=people.get(p.author_id);title.textContent=(person?.display_name||'Kullanıcı')+' · @'+(person?.handle||'');const body=document.createElement('p');body.textContent=p.body;const foot=document.createElement('small');foot.textContent=(lm.get(p.id)||0)+' beğeni · '+(cm.get(p.id)||0)+' yorum · '+new Date(p.created_at).toLocaleDateString('tr-TR');item.append(title,body,foot);list.append(item)}}catch(err){list.textContent='Gündemdeki yazılar getirilemedi: '+(err?.message||'Bağlantı hatası')}finally{busy=false}}
function enhance(){const menu=main.querySelector('.pati-explore-custom-menu');if(!menu||menu.querySelector('[data-buchee-trending]'))return;const b=document.createElement('button');b.type='button';b.dataset.bucheeTrending='1';b.innerHTML='Gündemdeki Tweetler <small>En çok beğenilen ve yorumlanan yazılar</small>';menu.append(b)}
document.addEventListener('click',e=>{if(e.target.closest('[data-buchee-trending]')){e.preventDefault();e.stopImmediatePropagation();const menu=main.querySelector('.pati-explore-custom-menu');if(menu)menu.hidden=true;open()}},true);
let queued=false;new MutationObserver(()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;enhance()})}).observe(main,{childList:true,subtree:true});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&getUI().hidden===false)close()});enhance()})();